USE peersync;
CREATE TABLE IF NOT EXISTS Notifications (notification_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(160) NOT NULL,message VARCHAR(500) NOT NULL,request_id INT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES Users(user_id) ON DELETE CASCADE,FOREIGN KEY(request_id) REFERENCES Support_Requests(request_id) ON DELETE SET NULL);
